(360, '_site_transient_update_plugins', 'O:8:\"stdClass\":5:{s:12:\"last_checked\";i:1770210296;s:8:\"response\";a:0:{}s:12:\"translations\";a:0:{}s:9:\"no_update\";a:5:{s:41:\"pojo-accessibility/pojo-accessibility.php\";O:8:\"stdClass\":10:{s:2:\"id\";s:32:\"w.org/plugins/pojo-accessibility\";s:4:\"slug\";s:18:\"pojo-accessibility\";s:6:\"plugin\";s:41:\"pojo-accessibility/pojo-accessibility.php\";s:11:\"new_version\";s:5:\"4.0.3\";s:3:\"url\";s:49:\"https://wordpress.org/plugins/pojo-accessibility/\";s:7:\"package\";s:67:\"https://downloads.wordpress.org/plugin/pojo-accessibility.4.0.3.zip\";s:5:\"icons\";a:2:{s:2:\"2x\";s:71:\"https://ps.w.org/pojo-accessibility/assets/icon-256x256.gif?rev=3443222\";s:2:\"1x\";s:71:\"https://ps.w.org/pojo-accessibility/assets/icon-128x128.gif?rev=3443222\";}s:7:\"banners\";a:2:{s:2:\"2x\";s:74:\"https://ps.w.org/pojo-accessibility/assets/banner-1544x500.png?rev=3443222\";s:2:\"1x\";s:73:\"https://ps.w.org/pojo-accessibility/assets/banner-772x250.png?rev=3443222\";}s:11:\"banners_rtl\";a:0:{}s:8:\"requires\";s:3:\"6.6\";}s:23:\"elementor/elementor.php\";O:8:\"stdClass\":10:{s:2:\"id\";s:23:\"w.org/plugins/elementor\";s:4:\"slug\";s:9:\"elementor\";s:6:\"plugin\";s:23:\"elementor/elementor.php\";s:11:\"new_version\";s:6:\"3.35.0\";s:3:\"url\";s:40:\"https://wordpress.org/plugins/elementor/\";s:7:\"package\";s:59:\"https://downloads.wordpress.org/plugin/elementor.3.35.0.zip\";s:5:\"icons\";a:2:{s:2:\"2x\";s:62:\"https://ps.w.org/elementor/assets/icon-256x256.gif?rev=3444228\";s:2:\"1x\";s:62:\"https://ps.w.org/elementor/assets/icon-128x128.gif?rev=3444228\";}s:7:\"banners\";a:2:{s:2:\"2x\";s:65:\"https://ps.w.org/elementor/assets/banner-1544x500.png?rev=3443226\";s:2:\"1x\";s:64:\"https://ps.w.org/elementor/assets/banner-772x250.png?rev=3443226\";}s:11:\"banners_rtl\";a:0:{}s:8:\"requires\";s:3:\"6.6\";}s:9:\"hello.php\";O:8:\"stdClass\":10:{s:2:\"id\";s:25:\"w.org/plugins/hello-dolly\";s:4:\"slug\";s:11:\"hello-dolly\";s:6:\"plugin